{"sql":"WITH cust_totals AS (
  SELECT c.CustomerId, c.FirstName || ' ' || c.LastName AS name, COUNT(i.InvoiceId) AS invoice_count, ROUND(COALESCE(SUM(i.Total),0),2) AS total_spent
  FROM Customer c
  LEFT JOIN Invoice i USING (CustomerId)
  GROUP BY c.CustomerId
)
SELECT * FROM cust_totals
WHERE total_spent = (SELECT MAX(total_spent) FROM cust_totals);
"}

